<script setup lang="ts">import{ref,onMounted,onUnmounted}from'vue';import{useGatewayStore}from'../stores/gateway';import Tooltip from'./Tooltip.vue'
interface Ms{name:string;transport:string;connected:boolean;tools:number;tool_names:string[];error?:string}
interface Mt{server:string;name:string}
interface Pr{installed:boolean;label:string;url:string;description:string}
interface Is{name:string;type:string;package:string;url:string;description:string;requires:string[]}
const g=useGatewayStore();const o=ref(false);const sr=ref<Ms[]>([]);const tl=ref<Mt[]>([]);const ld=ref(false)
const pr=ref<Record<string,Pr>>({});const mi=ref<Is[]>([])
async function lo(){ld.value=true;try{const r=await g.request<{servers:Ms[];tools:Mt[]}>('mcp.list',{});sr.value=r.servers||[];tl.value=r.tools||[]}catch{}finally{ld.value=false}
try{const r=await g.request<{prerequisites:Record<string,Pr>;servers:Is[]}>('mcp.install_info',{});pr.value=r.prerequisites||{};mi.value=r.servers||[]}catch{}}
function missingPrereqs():string[]{return Object.entries(pr.value).filter(([,v])=>!v.installed).map(([k])=>k)}
function dl(url:string){if(url)window.open(url,'_blank')}
function needDownload(name:string):Is|undefined{return mi.value.find(s=>s.name===name&&s.type==='download')}
function tg(){o.value=!o.value;if(o.value){lo();loSecrets()}}
const tokenOpen=ref('');const tokenVal=ref('');const tokenSaving=ref(false);const secretSt=ref<Record<string,Record<string,boolean>>>({})
async function loSecrets(){try{const r=await g.request<{secrets:Record<string,Record<string,boolean>>}>('mcp.secret_status',{});secretSt.value=r.secrets||{}}catch{}}
function tgToken(n:string){tokenOpen.value=tokenOpen.value===n?'':n;tokenVal.value=''}
async function saveToken(n:string){const v=tokenVal.value.trim();if(!v||tokenSaving.value)return;tokenSaving.value=true;try{const r=await g.request<{ok:boolean;reconnected:boolean}>('mcp.set_secret',{server:n,env_key:'GITHUB_PERSONAL_ACCESS_TOKEN',value:v});if(r?.ok){tokenOpen.value='';tokenVal.value='';await loSecrets();lo()}}catch{}finally{tokenSaving.value=false}}
const installing=ref('');const installErr=ref('');const manualOpen=ref('');const manualPath=ref('')
async function doInstall(n:string){if(installing.value)return;installing.value=n;installErr.value='';try{const r=await g.request<{ok:boolean;exe_path?:string;error?:string}>('mcp.install_server',{server:n});if(r?.ok){manualOpen.value='';await lo()}else{installErr.value=r?.error||'install failed';manualOpen.value=n}}catch(e){installErr.value=String(e);manualOpen.value=n}finally{installing.value=''}}
async function saveManualPath(n:string){const v=manualPath.value.trim();if(!v)return;installErr.value='';try{const r=await g.request<{ok:boolean;error?:string}>('mcp.install_server',{server:n,path:v});if(r?.ok){manualOpen.value='';manualPath.value='';await lo()}else{installErr.value=r?.error||'save failed'}}catch(e){installErr.value=String(e)}}
onMounted(()=>{const h=(e:MouseEvent)=>{if(!o.value)return;const el=e.target as HTMLElement;if(!el.closest('.mc-panel')&&!el.closest('.mc-btn'))o.value=false};document.addEventListener('mousedown',h);onUnmounted(()=>document.removeEventListener('mousedown',h))})
</script>
<template><Tooltip text="MCP Server Status" position="bottom"><button class="mc-btn" :class="{active:o}" @click="tg"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M7 17l-3 3"/><path d="M17 7l3-3"/><path d="M12 2l-2 4h4l-2-4z"/><path d="M10 6v4a2 2 0 002 2 2 2 0 002-2V6"/><path d="M8 12v4a4 4 0 008 0v-4"/></svg><span v-if="tl.length>0" class="mc-badge">{{tl.length}}</span></button></Tooltip>
<div v-if="o" class="mc-panel"><div class="mc-hdr"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M7 17l-3 3"/><path d="M17 7l3-3"/><path d="M12 2l-2 4h4l-2-4z"/><path d="M10 6v4a2 2 0 002 2 2 2 0 002-2V6"/><path d="M8 12v4a4 4 0 008 0v-4"/></svg><span class="mc-title">MCP Servers</span><Tooltip text="Refresh" position="bottom"><button class="mc-refresh" @click="lo"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><polyline points="23 4 23 10 17 10"/><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10"/></svg></button></Tooltip></div>
<div class="mc-body">
<div v-if="missingPrereqs().length>0" class="mc-prereqs"><div class="mc-prereqs-title">Missing Prerequisites</div><div v-for="k in missingPrereqs()" :key="k" class="mc-prereqs-item"><span class="mc-prereqs-name">{{k}}</span><span class="mc-prereqs-desc">{{pr[k]?.description}}</span><button v-if="pr[k]?.url" class="mc-prereqs-btn" @click="dl(pr[k].url)">{{pr[k]?.label}}</button></div></div>
<div v-if="ld&&sr.length===0" class="mc-empty">Loading...</div><div v-else-if="!ld&&sr.length===0" class="mc-empty">No MCP servers</div>
<div v-for="srv in sr" :key="srv.name" class="mc-srv" :class="{offline:!srv.connected}"><div class="mc-srv-hdr"><span class="mc-dot" :class="{on:srv.connected,off:!srv.connected}"/><span class="mc-srv-name">{{srv.name}}</span><span class="mc-srv-tools">{{srv.tools}} tools</span><span class="mc-status" :class="{up:srv.connected,down:!srv.connected}">{{srv.connected?'Connected':'Disconnected'}}</span></div><div v-if="srv.tool_names&&srv.tool_names.length>0" class="mc-tools"><span v-for="tn in srv.tool_names" :key="tn" class="mc-tool">{{tn}}</span></div><div class="mc-srv-ftp"><span class="mc-ftp-label">Transport</span><code class="mc-ftp-code">{{srv.transport}}</code></div><template v-if="srv.name==='github'"><div class="mc-srv-token"><span class="mc-token-label">Token</span><span class="mc-token-state" :class="{ok:secretSt[srv.name]?.['GITHUB_PERSONAL_ACCESS_TOKEN']}">{{ secretSt[srv.name]?.['GITHUB_PERSONAL_ACCESS_TOKEN'] ? 'Configured' : 'Not set' }}</span><button class="mc-token-btn" @click="tgToken(srv.name)">{{ tokenOpen===srv.name ? 'Close' : 'Set Token' }}</button></div><div v-if="tokenOpen===srv.name" class="mc-token-edit"><input type="password" v-model="tokenVal" class="mc-token-input" placeholder="ghp_..." spellcheck="false" @keydown.enter="saveToken(srv.name)"/><button class="mc-token-save" :disabled="!tokenVal.trim()||tokenSaving" @click="saveToken(srv.name)">{{ tokenSaving ? 'Saving...' : 'Save' }}</button></div></template><template v-if="!srv.connected&&needDownload(srv.name)"><div class="mc-srv-dl"><span>{{ installing===srv.name ? 'Installing...' : 'Not installed' }}</span><button class="mc-prereqs-btn" :disabled="!!installing" @click="doInstall(srv.name)">Install</button><button class="mc-prereqs-btn" @click="manualOpen=manualOpen===srv.name?'':srv.name">Set path</button></div><div v-if="manualOpen===srv.name" class="mc-token-edit"><input type="text" v-model="manualPath" class="mc-token-input" placeholder="C:\path\to\codebase-memory-mcp.exe" spellcheck="false" @keydown.enter="saveManualPath(srv.name)"/><button class="mc-token-save" :disabled="!manualPath.trim()" @click="saveManualPath(srv.name)">Save</button></div><div v-if="installErr&&manualOpen===srv.name" class="mc-srv-error">{{ installErr }}</div></template><div v-if="srv.error" class="mc-srv-error">{{srv.error}}</div></div></div></div></template>
